import fs from 'fs';
import path from 'path';

const PersistedMediaAssetType = {
  Image: 'image',
  Video: 'video',
} as const;

type PersistedMediaAssetType = typeof PersistedMediaAssetType[keyof typeof PersistedMediaAssetType];

const IMAGE_EXTENSIONS = new Set(['.png', '.jpg', '.jpeg', '.gif', '.webp', '.bmp', '.avif']);

const MIME_TO_EXTENSION: Record<string, string> = {
  'image/png': '.png',
  'image/jpeg': '.jpg',
  'image/jpg': '.jpg',
  'image/gif': '.gif',
  'image/webp': '.webp',
  'image/bmp': '.bmp',
  'image/avif': '.avif',
};

const EXTENSION_TO_MIME: Record<string, string> = {
  '.png': 'image/png',
  '.jpg': 'image/jpeg',
  '.jpeg': 'image/jpeg',
  '.gif': 'image/gif',
  '.webp': 'image/webp',
  '.bmp': 'image/bmp',
  '.avif': 'image/avif',
};

const VIDEO_EXTENSIONS = new Set(['.mp4', '.mov', '.webm']);

const VIDEO_MIME_TO_EXTENSION: Record<string, string> = {
  'video/mp4': '.mp4',
  'video/quicktime': '.mov',
  'video/webm': '.webm',
};

const VIDEO_EXTENSION_TO_MIME: Record<string, string> = {
  '.mp4': 'video/mp4',
  '.mov': 'video/quicktime',
  '.webm': 'video/webm',
};

const INVALID_FILE_NAME_PATTERN = /[<>:"/\\|?*�-]/g;

export interface RemoteGeneratedMediaAsset {
  type: string;
  url: string;
  outputIndex?: number;
  mimeType?: string;
  filename?: string;
}

export interface PersistedGeneratedImageAsset {
  type: PersistedMediaAssetType;
  url: string;
  originalUrl: string;
  mimeType: string;
  filename: string;
  filePath: string;
  localPath: string;
  outputIndex?: number;
}

export interface FailedGeneratedImageAsset {
  url: string;
  error: string;
}

export interface PersistGeneratedImageAssetsResult {
  saved: PersistedGeneratedImageAsset[];
  failed: FailedGeneratedImageAsset[];
}

interface FetchHeadersLike {
  get(name: string): string | null;
}

export interface FetchResponseLike {
  ok: boolean;
  status: number;
  statusText?: string;
  headers: FetchHeadersLike;
  arrayBuffer(): Promise<ArrayBuffer>;
}

export type FetchGeneratedAsset = (url: string) => Promise<FetchResponseLike>;

function normalizeImageExtension(extension: string): string {
  const normalized = extension.trim().toLowerCase();
  if (!normalized) return '';
  const withDot = normalized.startsWith('.') ? normalized : `.${normalized}`;
  return IMAGE_EXTENSIONS.has(withDot) ? withDot : '';
}

export function sanitizeGeneratedImageFileName(input: string | undefined, fallbackBase: string, extension: string): string {
  const parsed = path.parse((input || '').trim());
  const ext = normalizeImageExtension(extension)
    || (IMAGE_EXTENSIONS.has(parsed.ext.toLowerCase()) ? parsed.ext.toLowerCase() : '');
  const base = (parsed.name || fallbackBase)
    .replace(INVALID_FILE_NAME_PATTERN, '-')
    .replace(/\s+/g, ' ')
    .trim()
    .replace(/^\.+$/, '');
  const safeBase = base || fallbackBase;
  return `${safeBase}${ext}`;
}

function sanitizeGeneratedVideoFileName(input: string | undefined, fallbackBase: string, extension: string): string {
  const parsed = path.parse((input || '').trim());
  const ext = VIDEO_EXTENSIONS.has(parsed.ext.toLowerCase()) ? parsed.ext.toLowerCase() : extension;
  const base = (parsed.name || fallbackBase)
    .replace(INVALID_FILE_NAME_PATTERN, '-')
    .replace(/\s+/g, ' ')
    .trim()
    .replace(/^\.+$/, '');
  const safeBase = base || fallbackBase;
  return `${safeBase}${ext}`;
}

export function inferImageExtensionFromUrl(url: string): string | null {
  try {
    const parsed = new URL(url);
    const ext = path.extname(decodeURIComponent(parsed.pathname)).toLowerCase();
    return IMAGE_EXTENSIONS.has(ext) ? ext : null;
  } catch {
    return null;
  }
}

export function inferImageMimeTypeFromDataUrl(url: string): string | null {
  const trimmed = url.trim();
  if (!trimmed.toLowerCase().startsWith('data:')) return null;
  const comma = trimmed.indexOf(',');
  if (comma <= 5) return null;

  const mimeType = trimmed.slice(5, comma).split(';')[0]?.trim().toLowerCase() || '';
  return mimeType.startsWith('image/') ? mimeType : null;
}

function decodeImageDataUrl(url: string, assetMime: string): { buffer: Buffer; extension: string; mimeType: string } | null {
  const trimmed = url.trim();
  if (!trimmed.toLowerCase().startsWith('data:')) return null;

  const comma = trimmed.indexOf(',');
  if (comma <= 5) {
    throw new Error('Image data URL format is invalid');
  }

  const headerParts = trimmed.slice(5, comma).split(';').map(part => part.trim()).filter(Boolean);
  const dataMime = headerParts[0]?.toLowerCase() || '';
  if (!dataMime.startsWith('image/')) {
    throw new Error('Data URL is not an image');
  }
  if (!headerParts.slice(1).some(part => part.toLowerCase() === 'base64')) {
    throw new Error('Image data URL must be base64 encoded');
  }

  const base64 = trimmed.slice(comma + 1).replace(/\s+/g, '');
  if (!base64) {
    throw new Error('Image data URL is empty');
  }
  if (!/^[A-Za-z0-9+/]*={0,2}$/.test(base64) || base64.length % 4 === 1) {
    throw new Error('Image data URL base64 content is invalid');
  }

  const buffer = Buffer.from(base64, 'base64');
  if (buffer.length === 0) {
    throw new Error('Image data URL is empty');
  }

  const byteExtension = inferImageExtensionFromBytes(buffer);
  const extension = byteExtension
    || MIME_TO_EXTENSION[dataMime]
    || MIME_TO_EXTENSION[assetMime];
  if (!extension) {
    throw new Error('Image data URL does not declare a supported image format');
  }

  const mimeType = byteExtension
    ? EXTENSION_TO_MIME[byteExtension] || dataMime
    : MIME_TO_EXTENSION[dataMime]
      ? dataMime
      : MIME_TO_EXTENSION[assetMime]
        ? assetMime
        : EXTENSION_TO_MIME[extension] || 'application/octet-stream';

  return { buffer, extension, mimeType };
}

function inferVideoExtensionFromUrl(url: string): string | null {
  try {
    const parsed = new URL(url);
    const ext = path.extname(decodeURIComponent(parsed.pathname)).toLowerCase();
    return VIDEO_EXTENSIONS.has(ext) ? ext : null;
  } catch {
    return null;
  }
}

export function inferImageExtensionFromBytes(buffer: Buffer): string | null {
  if (buffer.length >= 8 && buffer.subarray(0, 8).equals(Buffer.from([0x89, 0x50, 0x4E, 0x47, 0x0D, 0x0A, 0x1A, 0x0A]))) {
    return '.png';
  }
  if (buffer.length >= 3 && buffer[0] === 0xFF && buffer[1] === 0xD8 && buffer[2] === 0xFF) {
    return '.jpg';
  }
  if (buffer.length >= 6) {
    const prefix = buffer.subarray(0, 6).toString('ascii');
    if (prefix === 'GIF87a' || prefix === 'GIF89a') return '.gif';
  }
  if (buffer.length >= 12 && buffer.subarray(0, 4).toString('ascii') === 'RIFF' && buffer.subarray(8, 12).toString('ascii') === 'WEBP') {
    return '.webp';
  }
  if (buffer.length >= 2 && buffer.subarray(0, 2).toString('ascii') === 'BM') {
    return '.bmp';
  }
  if (buffer.length >= 12 && buffer.subarray(4, 8).toString('ascii') === 'ftyp') {
    const brand = buffer.subarray(8, 12).toString('ascii');
    if (brand === 'avif' || brand === 'avis') return '.avif';
  }
  return null;
}

function inferVideoExtensionFromBytes(buffer: Buffer): string | null {
  // MP4/M4V: ftyp box at offset 4
  if (buffer.length >= 8 && buffer.subarray(4, 8).toString('ascii') === 'ftyp') {
    return '.mp4';
  }
  // WebM/Matroska: EBML header
  if (buffer.length >= 4 && buffer[0] === 0x1A && buffer[1] === 0x45 && buffer[2] === 0xDF && buffer[3] === 0xA3) {
    return '.webm';
  }
  return null;
}

async function resolveUniqueFilePath(directory: string, fileName: string): Promise<string> {
  const parsed = path.parse(fileName);
  let candidate = path.join(directory, fileName);
  let suffix = 2;

  while (true) {
    try {
      await fs.promises.stat(candidate);
      candidate = path.join(directory, `${parsed.name}-${suffix}${parsed.ext}`);
      suffix++;
    } catch (error) {
      if ((error as NodeJS.ErrnoException).code === 'ENOENT') {
        return candidate;
      }
      throw error;
    }
  }
}

export async function persistGeneratedImageAssets(options: {
  cwd: string;
  assets: RemoteGeneratedMediaAsset[];
  fetchAsset: FetchGeneratedAsset;
  now?: Date;
}): Promise<PersistGeneratedImageAssetsResult> {
  const cwd = options.cwd.trim();
  const imageAssets = options.assets.filter(asset => asset.type === PersistedMediaAssetType.Image && asset.url.trim());
  const saved: PersistedGeneratedImageAsset[] = [];
  const failed: FailedGeneratedImageAsset[] = [];

  if (!cwd || imageAssets.length === 0) {
    return { saved, failed };
  }

  await fs.promises.mkdir(cwd, { recursive: true });
  const now = options.now ?? new Date();
  const timestamp = [
    now.getFullYear(),
    String(now.getMonth() + 1).padStart(2, '0'),
    String(now.getDate()).padStart(2, '0'),
    '-',
    String(now.getHours()).padStart(2, '0'),
    String(now.getMinutes()).padStart(2, '0'),
    String(now.getSeconds()).padStart(2, '0'),
  ].join('');

  for (let index = 0; index < imageAssets.length; index++) {
    const asset = imageAssets[index];
    const url = asset.url.trim();

    try {
      const assetMime = asset.mimeType?.split(';')[0]?.trim().toLowerCase() || '';
      let buffer: Buffer;
      let extension: string;
      let mimeType: string;

      const dataUrlImage = decodeImageDataUrl(url, assetMime);
      if (dataUrlImage) {
        buffer = dataUrlImage.buffer;
        extension = dataUrlImage.extension;
        mimeType = dataUrlImage.mimeType;
      } else {
        const response = await options.fetchAsset(url);
        if (!response.ok) {
          throw new Error(`Download returned HTTP ${response.status}${response.statusText ? ` ${response.statusText}` : ''}`);
        }

        buffer = Buffer.from(await response.arrayBuffer());
        if (buffer.length === 0) {
          throw new Error('Downloaded image is empty');
        }

        const headerMime = response.headers.get('content-type')?.split(';')[0]?.trim().toLowerCase() || '';
        const byteExtension = inferImageExtensionFromBytes(buffer);
        extension = byteExtension
          || MIME_TO_EXTENSION[headerMime]
          || MIME_TO_EXTENSION[assetMime]
          || inferImageExtensionFromUrl(url)
          || '';
        if (!extension) {
          throw new Error('Downloaded file is not a recognized image');
        }

        if (byteExtension) {
          mimeType = EXTENSION_TO_MIME[byteExtension] || headerMime || assetMime || 'application/octet-stream';
        } else if (MIME_TO_EXTENSION[headerMime]) {
          mimeType = headerMime;
        } else if (MIME_TO_EXTENSION[assetMime]) {
          mimeType = assetMime;
        } else {
          mimeType = EXTENSION_TO_MIME[extension] || 'application/octet-stream';
        }
      }
      const fallbackBase = `generated-image-${timestamp}-${index + 1}`;
      const fileName = sanitizeGeneratedImageFileName(asset.filename, fallbackBase, extension);
      const filePath = await resolveUniqueFilePath(cwd, fileName);
      const tempPath = `${filePath}.download`;

      try {
        await fs.promises.writeFile(tempPath, buffer, { flag: 'wx' });
        await fs.promises.rename(tempPath, filePath);
      } catch (error) {
        await fs.promises.unlink(tempPath).catch(() => {});
        throw error;
      }

      saved.push({
        type: PersistedMediaAssetType.Image,
        url,
        originalUrl: url,
        mimeType,
        filename: path.basename(filePath),
        filePath,
        localPath: filePath,
        ...(Number.isInteger(asset.outputIndex) ? { outputIndex: asset.outputIndex } : {}),
      });
    } catch (error) {
      failed.push({
        url,
        error: error instanceof Error ? error.message : 'Failed to persist generated image',
      });
    }
  }

  return { saved, failed };
}

export async function persistGeneratedVideoAssets(options: {
  cwd: string;
  assets: RemoteGeneratedMediaAsset[];
  fetchAsset: FetchGeneratedAsset;
  now?: Date;
}): Promise<PersistGeneratedImageAssetsResult> {
  const cwd = options.cwd.trim();
  const videoAssets = options.assets.filter(asset => asset.type === PersistedMediaAssetType.Video && asset.url.trim());
  const saved: PersistedGeneratedImageAsset[] = [];
  const failed: FailedGeneratedImageAsset[] = [];

  if (!cwd || videoAssets.length === 0) {
    return { saved, failed };
  }

  await fs.promises.mkdir(cwd, { recursive: true });
  const now = options.now ?? new Date();
  const timestamp = [
    now.getFullYear(),
    String(now.getMonth() + 1).padStart(2, '0'),
    String(now.getDate()).padStart(2, '0'),
    '-',
    String(now.getHours()).padStart(2, '0'),
    String(now.getMinutes()).padStart(2, '0'),
    String(now.getSeconds()).padStart(2, '0'),
  ].join('');

  for (let index = 0; index < videoAssets.length; index++) {
    const asset = videoAssets[index];
    const url = asset.url.trim();

    try {
      const response = await options.fetchAsset(url);
      if (!response.ok) {
        throw new Error(`Download returned HTTP ${response.status}${response.statusText ? ` ${response.statusText}` : ''}`);
      }

      const buffer = Buffer.from(await response.arrayBuffer());
      if (buffer.length === 0) {
        throw new Error('Downloaded video is empty');
      }

      const headerMime = response.headers.get('content-type')?.split(';')[0]?.trim().toLowerCase() || '';
      const assetMime = asset.mimeType?.split(';')[0]?.trim().toLowerCase() || '';
      const extension = VIDEO_MIME_TO_EXTENSION[headerMime]
        || VIDEO_MIME_TO_EXTENSION[assetMime]
        || inferVideoExtensionFromUrl(url)
        || inferVideoExtensionFromBytes(buffer)
        || '.mp4';
      const mimeType = VIDEO_MIME_TO_EXTENSION[headerMime]
        ? headerMime
        : VIDEO_MIME_TO_EXTENSION[assetMime]
          ? assetMime
          : VIDEO_EXTENSION_TO_MIME[extension] || 'video/mp4';
      const fallbackBase = `generated-video-${timestamp}-${index + 1}`;
      const fileName = sanitizeGeneratedVideoFileName(asset.filename, fallbackBase, extension);
      const filePath = await resolveUniqueFilePath(cwd, fileName);
      const tempPath = `${filePath}.download`;

      try {
        await fs.promises.writeFile(tempPath, buffer, { flag: 'wx' });
        await fs.promises.rename(tempPath, filePath);
      } catch (error) {
        await fs.promises.unlink(tempPath).catch(() => {});
        throw error;
      }

      saved.push({
        type: PersistedMediaAssetType.Video,
        url,
        originalUrl: url,
        mimeType,
        filename: path.basename(filePath),
        filePath,
        localPath: filePath,
        ...(Number.isInteger(asset.outputIndex) ? { outputIndex: asset.outputIndex } : {}),
      });
    } catch (error) {
      failed.push({
        url,
        error: error instanceof Error ? error.message : 'Failed to persist generated video',
      });
    }
  }

  return { saved, failed };
}
